const upsertDraftRun = `-- name: UpsertDraftRun :one
INSERT INTO payroll_runs (tenant_id, tenant_source, driver_id, pay_period, pay_round, period_start, period_end, status,
  total_earnings_thb, total_deductions_thb, net_pay_thb)
VALUES ($1, 'driver', $2, $3, $4, $5,
  $6, 'draft', $7, $8, $9)
ON CONFLICT (driver_id, pay_period, pay_round) DO UPDATE
SET period_start         = EXCLUDED.period_start,
    period_end           = EXCLUDED.period_end,
    total_earnings_thb   = EXCLUDED.total_earnings_thb,
    total_deductions_thb = EXCLUDED.total_deductions_thb,
    net_pay_thb          = EXCLUDED.net_pay_thb
WHERE payroll_runs.status = 'draft' AND payroll_runs.tenant_id = EXCLUDED.tenant_id
RETURNING id, (xmax = 0)::boolean AS inserted
`

type UpsertDraftRunParams struct {
	TenantID           uuid.UUID
	DriverID           *uuid.UUID
	PayPeriod          string
	PayRound           string
	PeriodStart        time.Time
	PeriodEnd          time.Time
	TotalEarningsThb   float64
	TotalDeductionsThb float64
	NetPayThb          float64
}

type UpsertDraftRunRow struct {
	ID       uuid.UUID
	Inserted bool
}

// A driver's run of the round: created as draft, or rewritten while it is still draft in the same tenant (created_at
// kept); a run that left draft (or belongs to another tenant) returns no row and is left alone.
func (q *Queries) UpsertDraftRun(ctx context.Context, arg UpsertDraftRunParams) (UpsertDraftRunRow, error) {
	row := q.db.QueryRow(ctx, upsertDraftRun,
		arg.TenantID,
		arg.DriverID,
		arg.PayPeriod,
		arg.PayRound,
		arg.PeriodStart,
		arg.PeriodEnd,
		arg.TotalEarningsThb,
		arg.TotalDeductionsThb,
		arg.NetPayThb,
	)
	var i UpsertDraftRunRow
	err := row.Scan(&i.ID, &i.Inserted)
	return i, err
}
